$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$creds=json_decode(file_get_contents($argv[2]),true);$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function ok(bool $v,string $message='Assertion failed'):void{if(!$v)throw new RuntimeException($message);}
function test(string $n,callable $f):void{global $r;try{$f();$r['passed']++;$r['cases'][$n]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$n]=get_class($e).':'.$e->getMessage();}}
function deny(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException|PDOException){return;}throw new RuntimeException('Expected denial');}
function request():string{return bin2hex(random_bytes(16));}
function identity(array $m,string $user,string $pass):StaffSessionIdentity{global $db;$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$native=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($user,$pass,'m05c-synthetic');ok($native!==null);$s=[];StaffAccountService::bind($s,$native);$s['_merchant_login_outlet']=$m['loginOutlet'];return new StaffSessionIdentity($db,static fn()=>$s,getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));}
$pa=identity($a,$a['username'],$creds['owner_a_password']);$pb=identity($b,$b['username'],$creds['owner_b_password']);$pos=new StaffPos($db,$pa);$other=new StaffPos($db,$pb);$seating=new Seating($db,$pa);$seat=fn($op,$d)=>$seating->act($a['merchant'],$a['outlet'],request(),$op,$d)['result'];
$state=fn()=>$pos->load($a['merchant'],$a['outlet']);$find=fn($id)=>array_values(array_filter($state()['sessions'],fn($s)=>$s['service_id']===$id))[0];
if(($argv[3]??'')==='worker'){try{$result=$pos->submit($a['merchant'],$a['outlet'],$argv[4],$argv[5],$argv[6]);echo json_encode($result);exit(0);}catch(Throwable $e){fwrite(STDERR,get_class($e).':'.$e->getMessage());exit(1);}}
$rows=$state()['products'];$product=array_values(array_filter($rows,fn($p)=>$p['active']&&$p['available']&&$p['variant_active']))[0];$lines=[['product'=>(string)$product['product_id'],'variant'=>(string)$product['variant_id'],'quantity'=>'2','notes'=>'Less salt']];$table=null;$draft=null;
$inventory=[];foreach(['merchant_inventory_items','merchant_inventory_events','merchant_inventory_movements','merchant_inventory_recipes']as $t)$inventory[$t]=hash('sha256',serialize($db->query('SELECT * FROM '.$t.' ORDER BY 1')->fetchAll(PDO::FETCH_ASSOC)));
test('Occupied table session required and server-owned draft quote persists',function()use($seat,&$table,&$draft,$pos,$a,$lines,$state){$floor=$seat('floor',['id'=>'','version'=>'0','name'=>'POS Dining','active'=>'1'])['floor'];$table=$seat('table',['id'=>'','version'=>'0','floor'=>$floor['floor_id'],'name'=>'POS T4','capacity'=>'4','type'=>'standard','active'=>'1','notes'=>'Synthetic POS table'])['table'];deny(fn()=>$pos->save($a['merchant'],$a['outlet'],request(),'','0',$table['table_id'],$lines));$seat('status',['table'=>$table['table_id'],'version'=>'1','state'=>'OCCUPIED','minutes'=>'120','party'=>'2','reason'=>'Synthetic party seated']);$draft=$pos->save($a['merchant'],$a['outlet'],request(),'','0',$table['table_id'],$lines)['service'];ok(count($state()['sessions'])===1);ok($state()['sessions'][0]['draft']['quote']['totalPaise']>0);});
test('Save retry version conflict conflicting sessions and invalid fields rejected',function()use($pos,$a,$table,$draft,$lines,$find,$db){$d=$find($draft);$db->prepare('UPDATE merchant_service_sessions SET active_table=NULL WHERE service_id=?')->execute([$draft]);ok($find($draft)['active_table']===$table['table_id'],'Database must restore derived active-table slot');$key=request();$result=$pos->save($a['merchant'],$a['outlet'],$key,$draft,(string)$d['version'],$table['table_id'],$lines);ok($pos->save($a['merchant'],$a['outlet'],$key,$draft,(string)$d['version'],$table['table_id'],$lines)===$result);deny(fn()=>$pos->save($a['merchant'],$a['outlet'],request(),$draft,(string)$d['version'],$table['table_id'],$lines));deny(fn()=>$pos->save($a['merchant'],$a['outlet'],request(),'','0',$table['table_id'],$lines));$bad=$lines;$bad[0]['quantity']='0';deny(fn()=>$pos->save($a['merchant'],$a['outlet'],request(),$draft,'2',$table['table_id'],$bad));$bad[0]['quantity']='2';$bad[0]['price']='1';deny(fn()=>$pos->save($a['merchant'],$a['outlet'],request(),$draft,'2',$table['table_id'],$bad));});
test('Cross merchant outlet table draft and product identifiers denied',function()use($pos,$other,$a,$b,$table,$draft,$lines,$meta){deny(fn()=>$pos->load($b['merchant'],$b['outlet']));deny(fn()=>$pos->load($a['merchant'],$b['outlet']));deny(fn()=>$other->save($b['merchant'],$b['outlet'],request(),'','0',$table['table_id'],$lines));deny(fn()=>$other->submit($b['merchant'],$b['outlet'],request(),$draft,'2'));$bad=$lines;$bad[0]['product']=(string)$b['product'];deny(fn()=>$pos->save($a['merchant'],$a['outlet'],request(),$draft,'2',$table['table_id'],$bad));});
test('Active service interlock preserves occupied seating',function()use($seat,$seating,$a,$table){$t=array_values(array_filter($seating->load($a['merchant'],$a['outlet'])['tables'],fn($t)=>$t['table_id']===$table['table_id']))[0];deny(fn()=>$seat('status',['table'=>$t['table_id'],'version'=>(string)$t['version'],'state'=>'AVAILABLE','minutes'=>'1','party'=>'1','reason'=>'Unsafe release']));});
test('Changed price and unavailable product reject submission with complete rollback',function()use($db,$pos,$a,$draft,$product,$find){$id=(int)$product['variant_id'];$before=(int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn();$db->exec("UPDATE product_variants SET price_paise=price_paise+100 WHERE variant_id=$id");deny(fn()=>$pos->submit($a['merchant'],$a['outlet'],request(),$draft,(string)$find($draft)['version']));$db->exec("UPDATE product_variants SET price_paise=price_paise-100 WHERE variant_id=$id");$pid=(int)$product['product_id'];$db->exec("UPDATE products SET available=0 WHERE product_id=$pid");deny(fn()=>$pos->submit($a['merchant'],$a['outlet'],request(),$draft,(string)$find($draft)['version']));$db->exec("UPDATE products SET available=1 WHERE product_id=$pid");ok((int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn()===$before);ok($find($draft)['status']==='DRAFT');});
test('Audit failure rolls back shared order tasks notes and service status',function()use($db,$pos,$a,$draft,$find){$db->exec("CREATE TRIGGER m05c_audit_failure BEFORE INSERT ON merchant_service_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic audit failure'");$before=(int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn();try{deny(fn()=>$pos->submit($a['merchant'],$a['outlet'],request(),$draft,(string)$find($draft)['version']));ok((int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn()===$before);ok($find($draft)['status']==='DRAFT');}finally{$db->exec('DROP TRIGGER m05c_audit_failure');}});
test('Concurrent exact submission is idempotent with one order and station KOT set',function()use($db,$argv,$pos,$a,$draft,$find,&$r){$key=request();$version=(string)$find($draft)['version'];$before=(int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn();$children=[];for($i=0;$i<2;$i++){$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],'worker',$key,$draft,$version],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);ok(is_resource($proc));fclose($pipes[0]);$children[]=[$proc,$pipes];}$outputs=[];foreach($children as [$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);$r['workers'][]=['exit'=>$exit,'stdout'=>$out,'stderr'=>$err];ok($exit===0);$outputs[]=json_decode($out,true);}ok($outputs[0]===$outputs[1]);ok((int)$db->query('SELECT COUNT(*) FROM orders')->fetchColumn()===$before+1);$s=$find($draft);$q=$db->prepare('SELECT COUNT(*) FROM print_jobs WHERE order_id=?');$q->execute([$s['order_id']]);ok((int)$q->fetchColumn()===count($s['tasks']));ok($pos->submit($a['merchant'],$a['outlet'],$key,$draft,$version)===$outputs[0]);});
test('Attributed kitchen operations ready served and preserved seating/notes',function()use($db,$pos,$a,$draft,$find,$seating,$table){$s=$find($draft);deny(fn()=>$pos->finish($a['merchant'],$a['outlet'],request(),$draft,(string)$s['version']));foreach($s['tasks']as $t){ok(str_contains($t['payload_text'],'Less salt'),'KOT lost item notes');ok(str_contains($t['payload_text'],'TABLE POS T4'),'KOT lost table context');$pos->advance($a['merchant'],$a['outlet'],(int)$t['preparation_task_id'],'queued');deny(fn()=>$pos->advance($a['merchant'],$a['outlet'],(int)$t['preparation_task_id'],'queued'));$pos->advance($a['merchant'],$a['outlet'],(int)$t['preparation_task_id'],'preparing');}$pos->finish($a['merchant'],$a['outlet'],request(),$draft,(string)$find($draft)['version']);ok($find($draft)['status']==='SERVED');$t=array_values(array_filter($seating->load($a['merchant'],$a['outlet'])['tables'],fn($t)=>$t['table_id']===$table['table_id']))[0];ok($t['operational_state']==='OCCUPIED');$q=$db->prepare('SELECT DISTINCT changed_by FROM preparation_task_events WHERE order_id=?');$q->execute([$s['order_id']]);ok((bool)$q->fetchColumn());});
