$setup=new \Kios\MerchantOperations\RestaurantSetup($db,$pa);$setup->act($a['merchant'],$a['outlet'],(int)$setup->load($a['merchant'],$a['outlet'])['version'],request(),'staff-access',['user'=>$staff['kitchen']['user'],'role'=>'kitchen','enabled'=>'1','stations'=>[(string)$task['station_id']]]);
$kitchen=new StaffPos($db,identity($a,$staff['kitchen']['username'],$staff['kitchen']['password']));ok(count($kitchen->kitchen($a['merchant'],$a['outlet'])['tasks'])===1);$kitchen->advance($a['merchant'],$a['outlet'],(int)$task['preparation_task_id'],'queued');$kitchen->advance($a['merchant'],$a['outlet'],(int)$task['preparation_task_id'],'preparing');$cash->finish($a['merchant'],$a['outlet'],request(),$draft,'2');
});
